BEGIN;
CREATE OR REPLACE FUNCTION temporal_integrity_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'temporal integrity history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS temporal_clock_specs (spec_hash text PRIMARY KEY CHECK(spec_hash ~ '^[a-f0-9]{64}$'), domain_id text NOT NULL, scope_key text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS temporal_observations (observation_hash text PRIMARY KEY CHECK(observation_hash ~ '^[a-f0-9]{64}$'), spec_hash text NOT NULL REFERENCES temporal_clock_specs(spec_hash), scope_key text NOT NULL, expires_at timestamptz NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS temporal_validity_intervals (interval_hash text PRIMARY KEY CHECK(interval_hash ~ '^[a-f0-9]{64}$'), domain_id text NOT NULL, subject_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS temporal_causal_links (link_hash text PRIMARY KEY CHECK(link_hash ~ '^[a-f0-9]{64}$'), predecessor_hash text NOT NULL, successor_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(predecessor_hash <> successor_hash));
CREATE TABLE IF NOT EXISTS temporal_nonce_leases (lease_hash text PRIMARY KEY CHECK(lease_hash ~ '^[a-f0-9]{64}$'), domain_id text NOT NULL, nonce bigint NOT NULL CHECK(nonce >= 0), signer_fingerprint text NOT NULL, account_key text NOT NULL, request_hash text NOT NULL, idempotency_key text NOT NULL, state text NOT NULL CHECK(state IN ('reserved','signed','possibly_submitted','confirmed','rejected_unused','superseded')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(domain_id,nonce), UNIQUE(domain_id,idempotency_key));
CREATE TABLE IF NOT EXISTS temporal_nonce_transitions (transition_hash text PRIMARY KEY CHECK(transition_hash ~ '^[a-f0-9]{64}$'), lease_hash text NOT NULL REFERENCES temporal_nonce_leases(lease_hash), prior_state text, next_state text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS temporal_safety_decisions (decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'), scope_key text NOT NULL, operation text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('allow','block','unknown','safe_only')), idempotency_key text NOT NULL, expires_at timestamptz NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_key,idempotency_key));
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['temporal_clock_specs','temporal_observations','temporal_validity_intervals','temporal_causal_links','temporal_nonce_leases','temporal_nonce_transitions','temporal_safety_decisions'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I',item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION temporal_integrity_reject_mutation()',item,item); END LOOP; END $$;
COMMIT;
